mapper.select:
SELECT
-- 级联表的字段 ,xuanpai.xuanpai_name as xuanpaiName ,xuanpai.xuanpai_types as xuanpaiTypes ,xuanpai.zhuangtai_types as zhuangtaiTypes ,yonghu.yonghu_name as yonghuName ,yonghu.yonghu_phone as yonghuPhone
FROM yuyue_jilu a left JOIN xuanpai xuanpai ON a.xuanpai_id = xuanpai.id left JOIN yonghu yonghu ON a.yonghu_id = yonghu.id
and a.yonghu_id = #{params.yonghuId}
and a.xuanpai_id = #{params.xuanpaiId}
and a.yuyue_jilu_types = #{params.yuyueJiluTypes}
and xuanpai.xuanpai_name like CONCAT('%',#{params.xuanpaiName},'%')
and xuanpai.xuanpai_types = #{params.xuanpaiTypes}
and xuanpai.zhuangtai_types = #{params.zhuangtaiTypes}
and yonghu.yonghu_name like CONCAT('%',#{params.yonghuName},'%')
and yonghu.yonghu_phone like CONCAT('%',#{params.yonghuPhone},'%')
order by a.${params.orderBy} desc
